import{_ as e,c as r,o,ag as t}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"DragonOS","description":"","frontmatter":{"title":"DragonOS"},"headers":[],"relativePath":"radio/dragonos.md","filePath":"radio/dragonos.md","lastUpdated":null}'),n={name:"radio/dragonos.md"};function l(i,a,s,d,h,p){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="dragonos" tabindex="-1">DragonOS <a class="header-anchor" href="#dragonos" aria-label="Permalink to &quot;DragonOS&quot;">​</a></h1><h2 id="what-is-dragonos" tabindex="-1">What is DragonOS <a class="header-anchor" href="#what-is-dragonos" aria-label="Permalink to &quot;What is DragonOS&quot;">​</a></h2><p>DragonOS leverages the portability, security, and power of Lubuntu Linux as a delivery package and operating environment for a pre-installed suite of the most powerful and accessible open-source SDR software. DragonOS has verified support for various inexpensive and powerful SDR hardware, including RTL-SDR, HackRF One, LimeSDR, BladeRF, and many others.</p><p>Go to the source <a href="https://cemaxecuter.com/" target="_blank" rel="noreferrer">CEMAXECUTER</a></p><ul><li>Pre-configured Products including the WarDragon Kit+ found <a href="https://cemaxecuter.com/?post_type=product" target="_blank" rel="noreferrer">here</a><a href="#">Background</a></li></ul><h3 id="supported-devices" tabindex="-1">Supported Devices <a class="header-anchor" href="#supported-devices" aria-label="Permalink to &quot;Supported Devices&quot;">​</a></h3><ul><li><p><strong>Virtualized</strong></p><ul><li>VirtualBox</li><li>VMware</li></ul></li><li><p><strong>Raspberry Pi</strong></p><ul><li>Pi 3</li><li>Pi 4</li></ul></li><li><p><strong>Intel</strong></p></li><li><p><strong>ARM</strong></p></li></ul><h2 id="install-dragonos" tabindex="-1">Install DragonOS <a class="header-anchor" href="#install-dragonos" aria-label="Permalink to &quot;Install DragonOS&quot;">​</a></h2><h3 id="download-dragonos" tabindex="-1">Download DragonOS <a class="header-anchor" href="#download-dragonos" aria-label="Permalink to &quot;Download DragonOS&quot;">​</a></h3><ul><li><p><a href="https://sourceforge.net/projects/dragonos-focal/files/latest/download" target="_blank" rel="noreferrer">Download from SourceForge</a></p></li><li><p>DragonOS_FocalX_R29.iso (Torrent available)</p></li></ul><h3 id="prepare-usb-with-iso-file-for-live-boot-or-dual-boot-options" tabindex="-1">Prepare USB with ISO File for Live Boot or Dual-Boot Options <a class="header-anchor" href="#prepare-usb-with-iso-file-for-live-boot-or-dual-boot-options" aria-label="Permalink to &quot;Prepare USB with ISO File for Live Boot or Dual-Boot Options&quot;">​</a></h3><ul><li><p><a href="https://www.ventoy.net/en/download.html" target="_blank" rel="noreferrer">Ventoy</a> – Allows drag-and-drop of ISO files after USB is set up.</p></li><li><p><a href="https://www.balena.io/etcher/" target="_blank" rel="noreferrer">Etcher</a> – Lightweight and compatible with different operating systems.</p></li></ul><h3 id="boot-and-installation-options" tabindex="-1">Boot and Installation Options <a class="header-anchor" href="#boot-and-installation-options" aria-label="Permalink to &quot;Boot and Installation Options&quot;">​</a></h3><ul><li><p>Boot DragonOS from the live image.</p></li><li><p>Install DragonOS in a dual-boot configuration alongside Windows, macOS, or Linux.</p></li><li><p>Run DragonOS in a virtual machine using the downloaded ISO.</p></li></ul><h2 id="dragonos-guides" tabindex="-1">DragonOS Guides <a class="header-anchor" href="#dragonos-guides" aria-label="Permalink to &quot;DragonOS Guides&quot;">​</a></h2><p>DragonOS is highly supported and has many guides and walkthroughs. These are sorted by [or specific actions on the <a href="/radio/software-defined-radios-sdrs.html">https://www.youtube.com/channel/UC9U2kaqhE716J2WNSTcOghg DragonOS YouTube Channel</a>.</p><blockquote></blockquote><p>This channel is best described as a project aimed at making it as easy as possible for someone new to Linux and SDRs to run either a live Linux distro or install Linux and be up and running with not only popular, well-known, and easily installed SDR software, but also more challenging to install and/or compile software. Combined with YouTube videos, it ensures everyone’s on the same page and can follow along.</p><h2 id="additional-information" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h2><ul><li><p><a href="https://sourceforge.net/projects/dragonos-focal/" target="_blank" rel="noreferrer">DragonOS SourceForge Page</a></p></li><li><p><a href="https://www.youtube.com/channel/UC9U2kaqhE716J2WNSTcOghg" target="_blank" rel="noreferrer">DragonOS YouTube Channel</a></p></li><li><p><a href="https://www.patreon.com/cemaxecuter" target="_blank" rel="noreferrer">Patreon Support</a></p></li></ul><h3 id="for-support-or-questions" tabindex="-1">For Support or Questions <a class="header-anchor" href="#for-support-or-questions" aria-label="Permalink to &quot;For Support or Questions&quot;">​</a></h3><ul><li><p>Email: <a href="mailto:cemaxecuter@protonmail.com" target="_blank" rel="noreferrer">cemaxecuter@protonmail.com</a></p></li><li><p><a href="https://discord.gg/9uSC2un" target="_blank" rel="noreferrer">Join the DragonOS Discord</a></p></li><li><p>Matrix Channels:</p><ul><li><a href="https://matrix.to/#/#dragon-os:matrix.org" target="_blank" rel="noreferrer">DragonOS General Chat</a></li><li><a href="https://matrix.to/#/#dragon-os-qa:matrix.org" target="_blank" rel="noreferrer">DragonOS Q&amp;A</a></li><li><a href="https://matrix.to/#/#dragon-os-updates:matrix.org" target="_blank" rel="noreferrer">DragonOS Announcements</a></li></ul></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><p><a href="https://sourceforge.net/p/dragonos-focal/wiki/Home/" target="_blank" rel="noreferrer">DragonOS SourceForge Wiki</a></p></li><li><p><a href="https://www.ventoy.net/en/index.html" target="_blank" rel="noreferrer">Ventoy</a></p></li><li><p><a href="https://www.balena.io/what-is-balena" target="_blank" rel="noreferrer">Balena Etcher</a></p></li><li><p><a href="https://www.youtube.com/channel/UC9U2kaqhE716J2WNSTcOghg/about" target="_blank" rel="noreferrer">DragonOS YouTube Channel</a></p></li></ul><p>[Source Software]</p>',25)])])}const c=e(n,[["render",l]]);export{g as __pageData,c as default};
